```jsx
// CountdownTimer.jsx
import { useState, useEffect, useRef } from "react";

function formatTime(totalSeconds) {
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

export default function CountdownTimer({
  seconds,
  autoStart = true,
  onComplete,
}) {
  const [remaining, setRemaining] = useState(seconds);
  const [isRunning, setIsRunning] = useState(autoStart && seconds > 0);

  // Keep the latest callback without restarting the interval when it changes
  const onCompleteRef = useRef(onComplete);
  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  // Reset if the `seconds` prop changes
  useEffect(() => {
    setRemaining(seconds);
    setIsRunning(autoStart && seconds > 0);
  }, [seconds, autoStart]);

  // Ticking logic
  useEffect(() => {
    if (!isRunning) return;

    // Based on wall-clock time, so it doesn't drift or lag in background tabs
    const endTime = Date.now() + remaining * 1000;

    const id = setInterval(() => {
      const left = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
      setRemaining(left);

      if (left === 0) {
        clearInterval(id);
        setIsRunning(false);
        onCompleteRef.current?.();
      }
    }, 250);

    return () => clearInterval(id);
    // Intentionally only depends on isRunning: `remaining` is read when
    // starting/resuming, and we don't want to restart on every tick.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRunning]);

  const reset = () => {
    setIsRunning(false);
    setRemaining(seconds);
  };

  const isFinished = remaining === 0;

  return (
    <div style={{ textAlign: "center", fontFamily: "sans-serif" }}>
      <div
        role="timer"
        aria-live="off"
        style={{
          fontSize: "3rem",
          fontVariantNumeric: "tabular-nums",
          color: isFinished ? "crimson" : "inherit",
        }}
      >
        {formatTime(remaining)}
      </div>

      <div style={{ display: "flex", gap: 8, justifyContent: "center" }}>
        <button
          onClick={() => setIsRunning((r) => !r)}
          disabled={isFinished}
        >
          {isRunning ? "Pause" : "Start"}
        </button>
        <button onClick={reset}>Reset</button>
      </div>

      {isFinished && <p>Time's up!</p>}
    </div>
  );
}
```

